<?php require_once __DIR__ . '/../cdn.php'; \SimpleCdn\Cdn::enable([]); $nodesFile = __DIR__ . '/../nodes.json'; $cdnNodes = []; if (is_file($nodesFile)) { $content = @file_get_contents($nodesFile); if ($content !== false) { $decoded = @json_decode($content, true); if (is_array($decoded)) { $cdnNodes = $decoded; } } } $healthStatuses = []; if (!empty($cdnNodes)) { $healthStatuses = \SimpleCdn\Cdn::runHealthCheck($cdnNodes); } ?> <!DOCTYPE html> <html lang="zh-CN"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Simple CDN 后台 - 节点健康检查</title> <style> * { box-sizing: border-box; } body { font-family: system-ui, -apple-system, Segoe UI, Microsoft YaHei, sans-serif; background: #f5f7fa; color: #111; margin: 0; } .topbar { background: #fff; border-bottom: 1px solid #e2e8f0; padding: 12px 24px; display: flex; align-items: center; gap: 16px; } .topbar h1 { font-size: 16px; margin: 0; color: #0f172a; } .topbar a { color: #2563eb; text-decoration: none; font-size: 13px; } .topbar a:hover { text-decoration: underline; } .topbar .spacer { flex: 1; } .container { max-width: 1100px; margin: 24px auto; padding: 0 20px; } .card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 20px; } .card h2 { font-size: 18px; margin: 0 0 16px; color: #0f172a; } .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 24px; } .stat-card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 16px; } .stat-card .value { font-size: 30px; font-weight: 700; } .stat-card .label { font-size: 13px; color: #64748b; margin-top: 4px; } .stat-card .online { color: #059669; } .stat-card .offline { color: #dc2626; } .stat-card .unknown { color: #94a3b8; } .btn { display: inline-block; padding: 8px 14px; border: none; border-radius: 6px; font-size: 13px; cursor: pointer; text-decoration: none; } .btn:hover { opacity: 0.9; } .btn-primary { background: #2563eb; color: #fff; } .btn-primary:hover { background: #1d4ed8; } .btn-secondary { background: #f1f5f9; color: #334155; } .btn-secondary:hover { background: #e2e8f0; } .btn-sm { padding: 4px 8px; font-size: 12px; } .table { width: 100%; border-collapse: collapse; margin-top: 12px; } .table th { text-align: left; padding: 10px 12px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9; background: #fafbfc; } .table td { padding: 10px 12px; border-bottom: 1px solid #f1f5f9; font-size: 14px; } .table tr:hover { background: #f8fafc; } .badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 700; } .badge-online { background: #dcfce7; color: #166534; } .badge-offline { background: #fee2e2; color: #991b1b; } .badge-unknown { background: #f1f5f9; color: #64748b; } .muted { color: #64748b; font-size: 13px; } .empty { color: #94a3b8; font-style: italic; } .note { font-size: 13px; color: #64748b; margin-top: 16px; } </style> </head> <body> <div class="topbar"> <h1>节点健康检查</h1> <div class="spacer"></div> <a href="index.php" class="btn-secondary">← 返回仪表盘</a> </div> <div class="container"> $onlineCount = 0; $offlineCount = 0; $unknownCount = 0; foreach ($healthStatuses as $node) { if ($node['status'] === 'online') $onlineCount++; elseif ($node['status'] === 'offline') $offlineCount++; else $unknownCount++; } $totalCount = count($healthStatuses); ?> <div class="grid"> <div class="stat-card"> <div class="value echo $totalCount > 0 ? 'online' : 'unknown'; ?>">echo $totalCount; ?></div> <div class="label">节点总数</div> </div> <div class="stat-card"> <div class="value online">echo $onlineCount; ?></div> <div class="label">在线节点</div> </div> <div class="stat-card"> <div class="value offline">echo $offlineCount; ?></div> <div class="label">离线节点</div> </div> <div class="stat-card"> <div class="value unknown">echo $unknownCount; ?></div> <div class="label">未知状态</div> </div> </div> <div class="card"> <h2>节点状态详情</h2> <div style="display:flex;gap:12px;align-items:center;margin-bottom:16px;"> <button class="btn btn-primary" onclick="location.reload()">重新检测</button> <a href="nodes.php" class="btn btn-secondary btn-sm">管理节点</a> </div> if (empty($healthStatuses)): ?> <p class="empty">暂无节点健康数据。请先在<a href="nodes.php">多节点管理</a>中添加节点，或点击“重新检测”。</p> else: ?> <table class="table"> <thead> <tr> <th style="width:14%;">节点ID</th> <th style="width:18%;">名称</th> <th style="width:22%;">域名</th> <th style="width:14%;">状态</th> <th style="width:14%;">响应时间</th> <th style="width:12%;">检查次数</th> <th style="width:10%;">失败次数</th> <th style="width:auto;">最后检查</th> </tr> </thead> <tbody> foreach ($healthStatuses as $node): ?> <tr> <td>echo htmlspecialchars($node['id'] ?? ''); ?></td> <td>echo htmlspecialchars($node['name'] ?? ''); ?></td> <td>echo htmlspecialchars($node['domain'] ?? ''); ?></td> <td> <span class="badge echo $node['status'] === 'online' ? 'badge-online' : ($node['status'] === 'offline' ? 'badge-offline' : 'badge-unknown'); ?>"> echo $node['status'] === 'online' ? '在线' : ($node['status'] === 'offline' ? '离线' : '未知'); ?> </span> </td> <td>echo $node['response_time'] !== false ? $node['response_time'] . ' ms' : '—'; ?></td> <td>echo (int) ($node['check_count'] ?? 0); ?></td> <td>echo (int) ($node['fail_count'] ?? 0); ?></td> <td>echo htmlspecialchars($node['last_check'] ?? ''); ?></td> </tr> endforeach; ?> </tbody> </table> endif; ?> </div> <div class="card"> <h2>说明</h2> <div class="muted"> <ul style="margin:0; padding-left:20px;"> <li><strong>在线</strong>：节点 HTTP 探测返回 200-399 状态码，可正常提供缓存服务。</li> <li><strong>离线</strong>：节点不可访问或返回错误状态码，清理和调度时会自动跳过。</li> <li><strong>未知</strong>：尚未进行过健康检查，点击“重新检测”即可。</li> <li>检测结果按日期保存在 <code>health_checks/</code> 目录，无需数据库。</li> <li>离线节点在一键清理和多节点调度中会被自动跳过，不会影响整体操作。</li> </ul> </div> </div> </div> </body> </html>;